const rows=ref([]),page=ref(1),total=ref(0),selected=ref(null),showOriginal=ref(false),loading=ref(false),error=ref(''),options=ref(null),creating=ref(false),period=ref({}),preview=ref(null),form=ref(null),action=ref(null),basis=ref('');let epoch=0,alive=true,wasDeactivated=false,observedBoundary=false;
