const cohortValid=computed(()=>Array.isArray(props.applicationIds)&&props.applicationIds.length>0&&props.applicationIds.length<=256&&new Set(props.applicationIds).size===props.applicationIds.length&&props.applicationIds.every(supportId)),captureBody=computed(()=>({pool_id:props.poolId,period:period.value,application_ids:[...cohort.value].sort()}));
