function seedDemand(slot_id){return{slot_id};}
watch(()=>form.value?.cases.map(c=>c.requirements?.source_record_id),(values,previous)=>{if(!values||!preview.value)return;for(const[index,id]of values.entries()){if(!id||previous?.[index]===id)continue;const c=form.value.cases[index],raw=preview.value.source_records.find(r=>r.metadata.source_record_id===id)?.original?.payload;if(!raw)continue;c.room=seedDemand(raw.room.slot_id);c.roles=raw.roles.map(d=>seedDemand(d.slot_id));c.equipment=raw.equipment.map(d=>seedDemand(d.slot_id));}});
